import type { NextConfig } from 'next'
import bundleAnalyzer from '@next/bundle-analyzer'

const withBundleAnalyzer = bundleAnalyzer({
  enabled: process.env.ANALYZE === 'true',
})

const nextConfig: NextConfig = {
  output: 'standalone',
  reactStrictMode: true,
  // S19 perf — keep server-only deps out of the client bundle.
  // Prevents accidental client inclusion via transitive imports from lib/.
  serverExternalPackages: ['twilio', 'bullmq', 'ioredis', 'pdf-lib', 'qrcode'],
  experimental: {
    viewTransition: true,
    // S19 perf — Next.js rewrites named imports to subpath imports at build
    // time, dropping unused code from these high-traffic barrel-exporters.
    optimizePackageImports: [
      'date-fns',
      'lucide-react',
      '@tanstack/react-query',
      'sonner',
    ],
  },
  turbopack: {
    root: __dirname,
  },
  outputFileTracingRoot: __dirname,
  images: {
    remotePatterns: [
      {
        protocol: 'https',
        hostname: '*.supabase.co',
      },
    ],
  },
  async redirects() {
    // S13 — Navigation consolidation: old sub-routes → tab params on hub pages.
    // All 307 (temporary) — upgrade to 308 permanent once S14 confirms stability.
    return [
      // S18 — Today → Dashboard (permanent). Flipped from the S17 direction after
      // the sidebar label was renamed to "Dashboard" and the route was promoted.
      { source: '/today', destination: '/dashboard', permanent: true },

      // S17 — Commissions + Payroll → /payments tabs (permanent).
      // No /payroll/:path* wildcard — would break /payroll/runs/[id], /payroll/artist-summaries/[id],
      // /payroll/tax-forms/[id] deep links. Top-level redirects only; nested pages remain reachable
      // via their original URLs (linked from within the Payroll tab).
      { source: '/commissions', destination: '/payments?tab=commissions', permanent: true },
      { source: '/payroll', destination: '/payments?tab=payroll', permanent: true },

      // Appointments
      { source: '/waitlist', destination: '/appointments?tab=waitlist', permanent: false },

      // Artists/Team sub-routes
      { source: '/artists/schedules', destination: '/artists?tab=schedules', permanent: false },
      { source: '/guest-artists', destination: '/artists?tab=guest-artists', permanent: false },
      { source: '/settings/team/permissions', destination: '/artists?tab=permissions', permanent: false },

      // Inventory sub-routes
      { source: '/settings/ink-registry', destination: '/inventory?tab=ink-registry', permanent: false },

      // Clients sub-routes
      { source: '/settings/tags', destination: '/clients?tab=tags', permanent: false },
      { source: '/ai-design', destination: '/clients?tab=ai-design', permanent: false },

      // S24 Forms rename — /consent-forms → /forms. Permanent redirect so
      // external bookmarks / email links from pre-rename bookings keep
      // working. Wildcard version (below) handles nested paths.
      // CRITICAL: do NOT redirect '/consent-forms' → '/clients?tab=consent-forms'
      // (old S23 path). The Clients audit killed that sub-tab; the redirect
      // was left behind and silently broke the Forms surface.
      { source: '/consent-forms', destination: '/forms', permanent: true },
      { source: '/consent-forms/:path*', destination: '/forms/:path*', permanent: true },

      // S14 Settings Hub redirects — old flat URLs → new grouped /settings/{group}/{section}
      // All 307 (temporary) — upgrade to 308 after launch confirms stability.
      { source: '/settings/profile',      destination: '/settings/account/profile',      permanent: false },
      { source: '/settings/advanced',     destination: '/settings/account/advanced',     permanent: false },
      { source: '/settings/billing',      destination: '/settings/subscription/billing', permanent: false },
      { source: '/settings/services',     destination: '/settings/studio/services',      permanent: false },
      { source: '/settings/branding',     destination: '/settings/studio/branding',      permanent: false },
      { source: '/settings/booking-page', destination: '/settings/studio/booking-page',  permanent: false },
      { source: '/settings/policies',     destination: '/settings/studio/policies',      permanent: false },
      { source: '/settings/team',         destination: '/settings/team/members',         permanent: false },
      { source: '/settings/locations',    destination: '/locations',                     permanent: false },
      // NOTE: /settings/team/permissions — S13 already redirects to /artists?tab=permissions (S13 wins).
      // NOTE: /settings/ink-registry — S13 redirects to /inventory?tab=ink-registry.
      //   /settings/studio/ink-registry is accessible via sidebar nav directly.
      // NOTE: /settings root → handled by app/(app)/settings/page.tsx redirect().
    ]
  },

  async headers() {
    // Content-Security-Policy (QA #15 — OWASP A05)
    // Start strict; add per-vendor hashes in subsequent sprints.
    // 'unsafe-inline' is limited to styles to support Tailwind class injection.
    // Next.js 16 RSC inlines bootstrap/hydration scripts — requires 'unsafe-inline' on script-src.
    // 'unsafe-eval' is required for React dev-mode; keeps working in prod but can be dropped via nonce later.
    // Blob: scheme needed for workers (FullCalendar).
    const csp = [
      "default-src 'self'",
      "script-src 'self' 'unsafe-inline' 'unsafe-eval' blob:",
      "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
      "font-src 'self' data: https://fonts.gstatic.com",
      "img-src 'self' data: blob: https://*.supabase.co https://*.railway.app",
      "connect-src 'self' https://*.supabase.co wss://*.supabase.co https://app.posthog.com https://*.railway.app",
      "worker-src 'self' blob:",
      "frame-ancestors 'none'",
      "base-uri 'self'",
      "form-action 'self'",
      "object-src 'none'",
    ].join('; ')

    return [
      {
        source: '/:path*',
        headers: [
          {
            key: 'Strict-Transport-Security',
            value: 'max-age=63072000; includeSubDomains; preload',
          },
          { key: 'X-Frame-Options', value: 'DENY' },
          { key: 'X-Content-Type-Options', value: 'nosniff' },
          { key: 'Referrer-Policy', value: 'strict-origin-when-cross-origin' },
          { key: 'Content-Security-Policy', value: csp },
          { key: 'Permissions-Policy', value: 'camera=(), microphone=(), geolocation=()' },
        ],
      },
    ]
  },
  typescript: {
    ignoreBuildErrors: false,
  },
}

export default withBundleAnalyzer(nextConfig)

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { Plus, Sparkles } from 'lucide-react'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { Page, type PageAction } from '@/components/shared/Page'
import { EmptyState } from '@/components/shared/EmptyState'
import { Skeleton } from '@/components/ui/skeleton'
import { SubmissionsTable } from '@/components/consent/submissions/SubmissionsTable'
import { TemplatesGrid } from '@/components/consent/templates/TemplatesGrid'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import type { PageTab } from '@/components/shared/PageTabs'

export const metadata: Metadata = {
  title: 'Forms — InkOS',
}

// S24 Forms rebuild — Templates is the landing view (per Forms Scoping v1 spec).
// Submissions + Auto-send rules are secondary tabs. Rules is a placeholder tab
// in F1; real CRUD lands in F3 (consent_auto_send_rules migration + worker).
const VALID_TABS = ['templates', 'submissions', 'rules'] as const
type TabKey = (typeof VALID_TABS)[number]

interface SearchParams {
  tab?: string
}

function resolveTab(searchParams: SearchParams): TabKey {
  const requested = searchParams.tab as TabKey | undefined
  if (requested && VALID_TABS.includes(requested)) return requested
  return 'templates'
}

const FORM_TABS: PageTab[] = [
  {
    key: 'templates',
    label: 'Templates',
    href: '/forms?tab=templates',
    hidden: (role) => role === 'guest_artist',
  },
  {
    key: 'submissions',
    label: 'Submissions',
    href: '/forms?tab=submissions',
  },
  {
    key: 'rules',
    label: 'Auto-send rules',
    href: '/forms?tab=rules',
    hidden: (role) => role !== 'owner' && role !== 'admin',
  },
]

const TabSkeleton = () => (
  <div className="space-y-4">
    <Skeleton className="h-8 w-40" />
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
      {Array.from({ length: 6 }).map((_, i) => (
        <Skeleton key={i} className="h-40 w-full rounded-xl" />
      ))}
    </div>
  </div>
)

export default async function FormsPage({
  searchParams,
}: {
  searchParams: Promise<SearchParams>
}) {
  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { role, plan } = activeStudio
  const resolvedParams = await searchParams
  const activeTab = resolveTab(resolvedParams)

  const canManageTemplates = role === 'owner' || role === 'admin'

  // Primary action is tab-aware: + New template on Templates, nothing on
  // Submissions (Export all lives inside the table toolbar), + New rule
  // placeholder on Rules until F3 lands the real CRUD.
  const primaryAction: PageAction | undefined =
    activeTab === 'templates' && canManageTemplates
      ? { label: 'New template', href: '/forms/templates/new', icon: Plus }
      : undefined

  return (
    <Page
      title="Forms"
      subtitle="Consent, medical, photo release, and aftercare — all signed on client phones, stored forever."
      tabs={FORM_TABS}
      activeTab={activeTab}
      plan={plan as PlanTier}
      role={role as NavRole}
      {...(primaryAction ? { primaryAction } : {})}
    >
      {activeTab === 'templates' && (
        <Suspense fallback={<TabSkeleton />}>
          <TemplatesGrid />
        </Suspense>
      )}
      {activeTab === 'submissions' && (
        <Suspense fallback={<TabSkeleton />}>
          <SubmissionsTable />
        </Suspense>
      )}
      {activeTab === 'rules' && (
        <div className="py-12">
          <EmptyState
            icon={Sparkles}
            title="Auto-send rules are coming"
            description="Fire the right consent form at the right moment — on booking, for minors, after session completion, and more. Ships in the next Forms sprint."
            variant="coming-soon"
          />
        </div>
      )}
    </Page>
  )
}

/**
 * S18 — Breadcrumb builder.
 *
 * Replaces the legacy `[Studio] > [Location?] > [Page]` pattern in AppHeader
 * with a proper `Dashboard > [Section] > [Page/Tab/Entity]` hierarchy driven
 * by the current pathname + search params.
 *
 * Usage:
 *   const crumbs = getBreadcrumbs(pathname, searchParams.get('tab'), {})
 *
 * Detail pages can override a dynamic segment's label (e.g., "[id]" → client
 * name) by passing a `dynamicLabels` map keyed by the built-up sub-pathname:
 *   getBreadcrumbs('/clients/abc123', null, { '/clients/abc123': 'Jane Doe' })
 *   → [Dashboard, Clients, Jane Doe]
 */

export interface Crumb {
  /** Display label. */
  label: string
  /**
   * Optional href. When omitted, the crumb renders as the current-page anchor
   * (bold, non-link). The last crumb in a trail should always omit href.
   */
  href?: string
}

/** Static label for every known URL path segment. */
const SEGMENT_LABELS: Record<string, string> = {
