  team: 'Team',
  billing: 'Billing',
  usage: 'Usage',
  integrations: 'Integrations',
  profile: 'Profile',
  branding: 'Branding',
  services: 'Services',
  policies: 'Policies',
  'booking-page': 'Booking Page',
  'ink-registry': 'Ink Registry',
  advanced: 'Advanced',
  members: 'Members',
  // Generic CRUD
  new: 'New',
  edit: 'Edit',
  submissions: 'Submissions',
  templates: 'Templates',
  stocktake: 'Stocktake',
  // Client detail sub-tabs
  overview: 'Overview',
  photos: 'Photos',
  files: 'Files',
  comms: 'Messages',
  financial: 'Financial',
  // Payroll nested
  runs: 'Runs',
  'artist-summaries': 'Artist Summaries',
  'tax-forms': 'Tax Forms',
  // Studio settings nested
  'style-tags': 'Style Tags',
  campaigns: 'Campaigns',
  referrals: 'Referrals',
  // Admin
  admin: 'Admin',
