  // Legacy alias — if a user follows a stale /today link it will already have
  // been 301'd to /dashboard by next.config, but we include the label for safety.
  today: 'Dashboard',
}

/**
 * Tab hosts — pages that use `?tab=` to switch between sub-views. When the
 * current path matches a tab host and a `tab` param is present, append the
 * tab's label as the final crumb.
 */
const TAB_HOSTS: Record<string, Record<string, string>> = {
  '/payments': {
    transactions: 'Transactions',
    commissions: 'Commissions',
    payroll: 'Payroll',
  },
  '/artists': {
    roster: 'Roster',
    schedules: 'Schedules',
    guest: 'Guest Artists',
    permissions: 'Permissions',
  },
  '/appointments': {
    list: 'All',
    today: 'Today',
    waitlist: 'Waitlist',
  },
  '/forms': {
    submissions: 'Submissions',
    templates: 'Templates',
  },
  '/inbox': {
    all: 'All',
    deposits: 'Deposits',
    forms: 'Forms',
    clients: 'Clients',
    messages: 'Messages',
  },
  '/inventory': {
    stock: 'Stock',
    'ink-registry': 'Ink Registry',
  },
  '/clients': {
    all: 'All',
    tags: 'Tags',
    'ai-design': 'AI Design',
    'consent-forms': 'Consent Forms',
  },
  '/marketing': {
    campaigns: 'Campaigns',
    referrals: 'Referrals',
  },
}

/**
 * Produce a breadcrumb trail for the given pathname + tab.
 *
 * Rules:
 *  - Always starts with `Dashboard` (linking to `/dashboard`), except on
 *    `/dashboard` itself where Dashboard becomes the current-page crumb.
 *  - Each subsequent path segment becomes a crumb. Middle crumbs link to the
 *    accumulated sub-pathname; the last crumb omits its href.
 *  - Unknown segments fall back to the raw segment text (useful for UUIDs
 *    during detail-page navigation — the page itself can override via
 *    `dynamicLabels`).
 *  - Tab hosts append a third crumb when `?tab=` matches a known tab key.
 */
export function getBreadcrumbs(
  pathname: string,
  tab: string | null,
  dynamicLabels: Record<string, string> = {},
): Crumb[] {
  // Normalize: strip trailing slash
  const path = pathname === '/' ? '/dashboard' : pathname.replace(/\/$/, '')

  // /dashboard is the root — single-crumb, current page
  if (path === '/dashboard') {
    return [{ label: 'Dashboard' }]
  }

  // Admin section has its own root (not under Dashboard)
  if (path.startsWith('/admin')) {
    return buildTrail(path, tab, dynamicLabels, { rootLabel: 'Admin', rootHref: '/admin' })
  }

  return buildTrail(path, tab, dynamicLabels, { rootLabel: 'Dashboard', rootHref: '/dashboard' })
}

interface BuildTrailOptions {
  rootLabel: string
  rootHref: string
}

function buildTrail(
  path: string,
  tab: string | null,
  dynamicLabels: Record<string, string>,
  { rootLabel, rootHref }: BuildTrailOptions,
): Crumb[] {
  const crumbs: Crumb[] = [{ label: rootLabel, href: rootHref }]

  const segments = path.split('/').filter(Boolean)
  // Skip the root segment ONLY when path actually starts with rootHref
  // (e.g., "/admin/studios" with rootHref="/admin" strips the leading "admin").
  // For virtual roots like "/dashboard" above "/inbox", the path does NOT
  // contain "dashboard" as a segment — we keep all segments and accumulate
  // the built path from empty, not from rootHref.
  const rootPrefix = rootHref === '/' ? '' : rootHref
  const pathStartsWithRoot = rootPrefix !== '' && (path === rootPrefix || path.startsWith(rootPrefix + '/'))
  const rootSegments = rootPrefix.split('/').filter(Boolean)
  const relativeSegments = pathStartsWithRoot ? segments.slice(rootSegments.length) : segments

  let built = pathStartsWithRoot ? rootPrefix : ''
  relativeSegments.forEach((seg, i) => {
    built += '/' + seg
    const isLast = i === relativeSegments.length - 1
    const overrideLabel = dynamicLabels[built]
    const label =
      overrideLabel ??
      SEGMENT_LABELS[seg] ??
      // Fallback: title-case the segment (swap - → space)
      seg.replace(/-/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase())

    const isCurrent = isLast && !isTabCrumbPending(path, tab)
    const crumb: Crumb = isCurrent ? { label } : { label, href: built }
    crumbs.push(crumb)
  })

  // Append tab crumb if current path is a tab host and tab is set
  const tabLabels = TAB_HOSTS[path]
  if (tabLabels && tab && tabLabels[tab]) {
    crumbs.push({ label: tabLabels[tab] })
  }

  return crumbs
}

function isTabCrumbPending(path: string, tab: string | null): boolean {
  if (!tab) return false
  const tabLabels = TAB_HOSTS[path]
  return !!tabLabels && tab in tabLabels
}

/**
 * Server-side breadcrumb resolver.
 *
 * Consumed by `app/(app)/layout.tsx` to populate the `dynamicLabels` map
 * passed to `getBreadcrumbs()` in AppHeader. Pattern-matches the current
 * pathname against known detail-route patterns and parallel-queries the
 * entity label for each match.
 *
 * Caching: wrapped in React `cache()` — if anything else in the tree calls
 * `resolveDynamicLabels` with the same supabase client + pathname, it
 * returns the memoized result.
 *
 * Failure mode: any resolver that errors (RLS denial, deleted entity,
 * network blip) simply omits that key from the result. `getBreadcrumbs`
 * falls back to the title-cased UUID segment, which renders gracefully.
 */
import { cache } from 'react'
import type { SupabaseClient } from '@supabase/supabase-js'

// Typed opaque shape — resolver bodies use any-ish shapes to avoid importing
// the giant Database generic; types.ts may not have every table either.
type SB = SupabaseClient

type Resolver = {
  pattern: RegExp
  pathKeyFrom: (match: RegExpMatchArray) => string
  resolve: (supabase: SB, id: string) => Promise<string | null>
}

const ANY_ID_CAPTURE = '([^/]+)'

function formatMonthYear(isoDate: string): string {
  const d = new Date(isoDate)
  if (Number.isNaN(d.getTime())) return isoDate
  return d.toLocaleDateString('en-US', { month: 'short', year: 'numeric' })
}

function formatShortDate(iso: string): string {
  const d = new Date(iso)
  if (Number.isNaN(d.getTime())) return iso
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
}

/**
 * Safely read a single column from a single row. Returns null on any error
 * (RLS denial, deleted row, network blip, unknown table).
 */
async function safeRead<T>(fn: () => Promise<{ data: T | null; error: unknown }>): Promise<T | null> {
  try {
    const { data, error } = await fn()
    if (error) return null
    return data
  } catch {
    return null
  }
}

const RESOLVERS: Resolver[] = [
  // /clients/{id}[/...]
  {
    pattern: new RegExp(`^/clients/${ANY_ID_CAPTURE}(?:/|$)`),
    pathKeyFrom: (m) => `/clients/${m[1]}`,
    resolve: async (supabase, id) => {
      const data = await safeRead<{ first_name: string | null; last_name: string | null }>(
        async () => await supabase.from('clients').select('first_name, last_name').eq('id', id).maybeSingle(),
      )
      if (!data) return null
      const name = `${data.first_name ?? ''} ${data.last_name ?? ''}`.trim()
      return name.length > 0 ? name : null
    },
  },

  // /artists/{id}[/...]
  {
    pattern: new RegExp(`^/artists/${ANY_ID_CAPTURE}(?:/|$)`),
    pathKeyFrom: (m) => `/artists/${m[1]}`,
    resolve: async (supabase, id) => {
      const data = await safeRead<{ display_name: string | null }>(
        async () => await supabase.from('artists').select('display_name').eq('id', id).maybeSingle(),
      )
      return data?.display_name ?? null
    },
  },

  // /guest-artists/{id}
  {
    pattern: new RegExp(`^/guest-artists/${ANY_ID_CAPTURE}(?:/|$)`),
    pathKeyFrom: (m) => `/guest-artists/${m[1]}`,
    resolve: async (supabase, id) => {
      const engagement = await safeRead<{ artist_id: string }>(
        async () => await supabase.from('guest_artist_engagements').select('artist_id').eq('id', id).maybeSingle(),
      )
      if (!engagement?.artist_id) return null
      const artist = await safeRead<{ display_name: string | null }>(
        async () => await supabase.from('artists').select('display_name').eq('id', engagement.artist_id).maybeSingle(),
      )
      return artist?.display_name ?? null
    },
  },

  // /appointments/{id}[/...]
  {
    pattern: new RegExp(`^/appointments/${ANY_ID_CAPTURE}(?:/|$)`),
    pathKeyFrom: (m) => `/appointments/${m[1]}`,
    resolve: async (supabase, id) => {
      const data = await safeRead<{ scheduled_at: string | null; booking_token: string | null }>(
        async () => await supabase.from('bookings').select('scheduled_at, booking_token').eq('id', id).maybeSingle(),
      )
      if (!data) return null
      if (data.scheduled_at) return `Booking — ${formatShortDate(data.scheduled_at)}`
      return data.booking_token ?? null
    },
  },

  // /bookings/{id}
  {
    pattern: new RegExp(`^/bookings/${ANY_ID_CAPTURE}(?:/|$)`),
    pathKeyFrom: (m) => `/bookings/${m[1]}`,
    resolve: async (supabase, id) => {
      const data = await safeRead<{ scheduled_at: string | null; booking_token: string | null }>(
        async () => await supabase.from('bookings').select('scheduled_at, booking_token').eq('id', id).maybeSingle(),
      )
      if (!data) return null
      if (data.scheduled_at) return `Booking — ${formatShortDate(data.scheduled_at)}`
      return data.booking_token ?? null
    },
  },

  // /projects/{id}[/...]
  {
    pattern: new RegExp(`^/projects/${ANY_ID_CAPTURE}(?:/|$)`),
    pathKeyFrom: (m) => `/projects/${m[1]}`,
    resolve: async (supabase, id) => {
      const data = await safeRead<{ name: string | null }>(
        async () => await supabase.from('projects').select('name').eq('id', id).maybeSingle(),
      )
      return data?.name ?? null
    },
  },

  // /flash-events/{id}[/...]
  {
    pattern: new RegExp(`^/flash-events/${ANY_ID_CAPTURE}(?:/|$)`),
    pathKeyFrom: (m) => `/flash-events/${m[1]}`,
    resolve: async (supabase, id) => {
      const data = await safeRead<{ title: string | null }>(
        async () => await supabase.from('flash_events').select('title').eq('id', id).maybeSingle(),
      )
      return data?.title ?? null
    },
  },

  // /locations/{id}
  {
    pattern: new RegExp(`^/locations/${ANY_ID_CAPTURE}(?:/|$)`),
    pathKeyFrom: (m) => `/locations/${m[1]}`,
    resolve: async (supabase, id) => {
      const data = await safeRead<{ name: string | null }>(
        async () => await supabase.from('locations').select('name').eq('id', id).maybeSingle(),
      )
      return data?.name ?? null
    },
  },

  // /payroll/runs/{id}
  {
    pattern: new RegExp(`^/payroll/runs/${ANY_ID_CAPTURE}(?:/|$)`),
    pathKeyFrom: (m) => `/payroll/runs/${m[1]}`,
    resolve: async (supabase, id) => {
      const data = await safeRead<{ period_start: string | null }>(
        async () => await supabase.from('payroll_runs').select('period_start').eq('id', id).maybeSingle(),
      )
      if (!data?.period_start) return null
      return `Run — ${formatMonthYear(data.period_start)}`
    },
  },

  // /forms/submissions/{id}
  {
    pattern: new RegExp(`^/forms/submissions/${ANY_ID_CAPTURE}(?:/|$)`),
    pathKeyFrom: (m) => `/forms/submissions/${m[1]}`,
    resolve: async (supabase, id) => {
      const data = await safeRead<{ signer_name: string | null }>(
        async () => await supabase.from('consent_form_submissions').select('signer_name').eq('id', id).maybeSingle(),
      )
      return data?.signer_name ?? null
    },
  },

  // /messages/{conversationId}
  {
    pattern: new RegExp(`^/messages/${ANY_ID_CAPTURE}(?:/|$)`),
    pathKeyFrom: (m) => `/messages/${m[1]}`,
    resolve: async (supabase, id) => {
      const data = await safeRead<{ display_name: string | null }>(
        async () => await supabase.from('conversations').select('display_name').eq('id', id).maybeSingle(),
      )
      return data?.display_name ?? null
    },
  },

  // /admin/studios/{id}
  {
    pattern: new RegExp(`^/admin/studios/${ANY_ID_CAPTURE}(?:/|$)`),
    pathKeyFrom: (m) => `/admin/studios/${m[1]}`,
    resolve: async (supabase, id) => {
      const data = await safeRead<{ name: string | null }>(
        async () => await supabase.from('studios').select('name').eq('id', id).maybeSingle(),
      )
      return data?.name ?? null
    },
  },
]

/**
 * Resolve dynamic breadcrumb labels for the given pathname.
 *
 * Returns a map keyed by pathname prefix → human-readable label.
 * Example: `{ '/clients/abc123': 'Jane Doe' }`.
 *
 * The resulting map is passed to `getBreadcrumbs(pathname, tab, dynamicLabels)`
 * in AppHeader. Keys that don't match any resolver simply aren't in the map
 * (breadcrumb falls back to title-cased segment).
 */
export const resolveDynamicLabels = cache(
  async (supabase: SB, pathname: string): Promise<Record<string, string>> => {
    const matches = RESOLVERS.map((r) => {
      const m = pathname.match(r.pattern)
      if (!m || !m[1]) return null
      return {
        pathKey: r.pathKeyFrom(m),
        id: m[1],
        resolve: r.resolve,
      }
    }).filter((x): x is { pathKey: string; id: string; resolve: Resolver['resolve'] } => x !== null)

    if (matches.length === 0) return {}

    const results = await Promise.all(
      matches.map(async ({ pathKey, id, resolve }) => {
        const label = await resolve(supabase, id)
        return label ? ([pathKey, label] as const) : null
      }),
    )

    const out: Record<string, string> = {}
    for (const r of results) {
      if (r) out[r[0]] = r[1]
    }
    return out
  },
)

