        {/* S24 — the page-level <Page primaryAction> owns "+ New template".
            No duplicate CTA here. */}
      </div>

      {/* Loading */}
      {isLoading && (
        <div className="flex items-center justify-center py-16 text-muted-foreground">
          <Loader2 aria-hidden="true" className="h-5 w-5 animate-spin" />
        </div>
      )}

      {/* Error */}
      {!isLoading && error && (
        <div className="rounded-lg border border-destructive/30 bg-destructive/5 p-4 text-sm text-destructive">
          {error}
        </div>
      )}

      {/* Empty */}
      {!isLoading && !error && templates.length === 0 && (
        <EmptyState
          icon={FileSignature}
          title="No templates yet"
          description="Create your first consent form template to start collecting signatures — or wait a moment for the 6 InkOS defaults to seed."
          cta={{
            label: '+ New template',
            onClick: () => router.push('/forms/templates/new'),
          }}
          variant="first-time"
        />
      )}

      {/* Grid */}
      {!isLoading && !error && templates.length > 0 && (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
          {templates.map((t) => (
            <TemplateCard key={t.id} template={t} onRefresh={fetchTemplates} />
          ))}
        </div>
      )}
    </div>
  )
}

import { createServerClient } from '@supabase/ssr'
import { NextResponse, type NextRequest } from 'next/server'
import type { Database } from './types'

/**
 * Updates the session on every request to prevent session expiry.
 *
 * CRITICAL: This function rewrites cookies on BOTH the request (for downstream
 * reads in the same request cycle) AND the response (for the browser to send
 * the updated session token on the next request).
 *
 * This is the Next.js 16 pattern — proxy.ts calls this, not middleware.ts.
 */
export async function updateSession(request: NextRequest) {
  // Inject x-pathname header so server components (layouts) can read the
  // current pathname via `headers()`. Consumed by lib/breadcrumbs/resolve.ts.
  const requestHeaders = new Headers(request.headers)
  requestHeaders.set('x-pathname', request.nextUrl.pathname)

  let supabaseResponse = NextResponse.next({ request: { headers: requestHeaders } })

  const supabase = createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll()
        },
        setAll(cookiesToSet) {
          // Write on the request so downstream server components can read it
          cookiesToSet.forEach(({ name, value }) => request.cookies.set(name, value))
          // Rebuild the response with the updated request cookies + pathname header
          supabaseResponse = NextResponse.next({ request: { headers: requestHeaders } })
          // Write on the response so the browser stores the refreshed token
          cookiesToSet.forEach(({ name, value, options }) =>
            supabaseResponse.cookies.set(name, value, options)
          )
        },
      },
    }
  )

  // IMPORTANT: Always use getUser() — never getSession() for auth checks.
  // getUser() validates the JWT against the Supabase server.
  const {
    data: { user },
  } = await supabase.auth.getUser()

  const path = request.nextUrl.pathname

  // Redirect unauthenticated users away from protected routes
  if (!user) {
    const isProtected =
      path.startsWith('/dashboard') ||
      path.startsWith('/calendar') ||
      path.startsWith('/appointments') ||
      path.startsWith('/waitlist') ||
      path.startsWith('/clients') ||
      path.startsWith('/forms') ||
      path.startsWith('/ai-design') ||
      path.startsWith('/artists') ||
      path.startsWith('/guest-artists') ||
      path.startsWith('/inventory') ||
      path.startsWith('/commissions') ||
      path.startsWith('/payroll') ||
      path.startsWith('/payments') ||
      path.startsWith('/locations') ||
      path.startsWith('/marketing') ||
      path.startsWith('/settings') ||
      path.startsWith('/admin')

    if (isProtected) {
      const redirectUrl = request.nextUrl.clone()
      redirectUrl.pathname = '/login'
      redirectUrl.searchParams.set('redirectedFrom', path)
      return NextResponse.redirect(redirectUrl)
    }

    return supabaseResponse

